import type {Role} from '@github-ui/role-assignments/types/role-assignments'
import getRoleIcon from '@github-ui/role-assignments/utils/icon-map'
import {testIdProps} from '@github-ui/test-id-props'
import {IdBadgeIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu} from '@primer/react'

interface RolePickerProps {
  selectedRole?: Role
  availableRoles?: Role[]
  onSelect: (role: Role | null) => void
}

export function RolePicker({selectedRole, availableRoles, onSelect}: RolePickerProps) {
  const allOption = 'All'

  return (
    <ActionMenu>
      <ActionMenu.Button leadingVisual={IdBadgeIcon} {...testIdProps('role-picker-button')}>
        <span className="fgColor-muted">Role: </span>
        <span>{selectedRole?.name || allOption}</span>
      </ActionMenu.Button>
      <ActionMenu.Overlay>
        <ActionList selectionVariant="single">
          <ActionList.Item key="all-roles" selected={!selectedRole} onSelect={() => onSelect(null)}>
            <ActionList.LeadingVisual>
              <IdBadgeIcon />
            </ActionList.LeadingVisual>
            {allOption}
          </ActionList.Item>
          {availableRoles?.map(role => (
            <ActionList.Item key={role.id} selected={role.id === selectedRole?.id} onSelect={() => onSelect(role)}>
              <ActionList.LeadingVisual data-testid={`role-icon`}>{getRoleIcon(role.octicon)}</ActionList.LeadingVisual>
              {role.name}
            </ActionList.Item>
          ))}
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}
