import {IdBadgeIcon, PeopleIcon} from '@primer/octicons-react'
import {StaticFilterProvider} from '@github-ui/filter-core/providers'
import {IS_KEY, SelectedTab} from '../types/selected-tab'
import {
  FilterProviderType,
  type FilterKey,
  type FilterSuggestion,
  type SuppliedFilterProviderOptions,
} from '@github-ui/filter-core'
import {FilterQueryParser, isFilterBlock} from '@github-ui/filter-core'
import type {Role} from '@github-ui/role-assignments/types/role-assignments'
import {getRoleIconComponent} from '@github-ui/role-assignments/utils/icon-map'

class AssigneeTypeFilterProvider extends StaticFilterProvider {
  constructor() {
    const filterKey: FilterKey = {
      displayName: 'Assignee type',
      key: IS_KEY,
      priority: 2,
      icon: PeopleIcon,
      description: 'Filter by assignee type. Default: user',
    }

    const filterSuggestions: FilterSuggestion[] = [
      {value: SelectedTab.User, displayName: 'User', priority: 1},
      {value: SelectedTab.Team, displayName: 'Team', priority: 2},
    ]

    const filterOptions: SuppliedFilterProviderOptions = {
      filterTypes: {multiKey: false, multiValue: false, valueless: false, exclusive: false, hasValue: false},
    }

    super(filterKey, filterSuggestions, filterOptions)
    this.type = FilterProviderType.Select
  }
}

class RoleFilterProvider extends StaticFilterProvider {
  constructor(availableRoles: Role[] = []) {
    const filterKey: FilterKey = {
      displayName: 'Role',
      key: 'role',
      priority: 1,
      icon: IdBadgeIcon,
      description: 'Filter by role',
    }

    const filterSuggestions: FilterSuggestion[] = availableRoles.map((role, index) => ({
      value: role.name,
      displayName: role.name,
      icon: getRoleIconComponent(role.octicon),
      priority: index + 1,
    }))

    const filterOptions: SuppliedFilterProviderOptions = {
      filterTypes: {multiKey: false, multiValue: false, valueless: false, exclusive: false, hasValue: false},
    }

    super(filterKey, filterSuggestions, filterOptions)
  }
}

export function createAssignmentFilterProviders(availableRoles: Role[] = []) {
  if (availableRoles.length === 0) {
    return [assigneeTypeFilterProvider]
  }

  const roleFilterProvider = new RoleFilterProvider(availableRoles)
  return [assigneeTypeFilterProvider, roleFilterProvider]
}

const assigneeTypeFilterProvider = new AssigneeTypeFilterProvider()

// returns true if there is a search query other than `is` filter
export function hasNonAssigneeSearchQuery(query: string): boolean {
  if (!query.trim()) {
    return false
  }

  const filterQueryParser = new FilterQueryParser([assigneeTypeFilterProvider])
  const parsedQuery = filterQueryParser.parse(query)

  return parsedQuery.blocks.some(b => !(isFilterBlock(b) && b.key.value === IS_KEY))
}
