import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {
  RoleType,
  type ActorRoleAssignment,
  type AvatarOrg,
  type Role,
} from '@github-ui/role-assignments/types/role-assignments'
import {PageHeader} from '@primer/react'
import {RoleAssignmentsTable} from '../components/RoleAssignmentsTable'
import type {SelectedTab} from '../types/selected-tab'
import {RoutingProvider} from '@github-ui/role-assignments/routing-provider'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'

export interface EnterpriseRoleAssignmentsPayload {
  slug: string
  assignments: ActorRoleAssignment[]
  teamsCount: number
  usersCount: number
  currentPage: number
  pageCount: number
  hasWriteAccess: boolean
  selectedTab: SelectedTab
  canViewEnterpriseTeams: boolean
  avatarOrgs?: AvatarOrg[]
  selectedRole?: Role
  availableRoles?: Role[]
}

export function EnterpriseRoleAssignments() {
  const {
    slug,
    assignments,
    teamsCount,
    usersCount,
    currentPage,
    pageCount,
    hasWriteAccess,
    selectedTab,
    canViewEnterpriseTeams,
    avatarOrgs,
    selectedRole,
    availableRoles,
  } = useRoutePayload<EnterpriseRoleAssignmentsPayload>()
  return (
    <RoutingProvider slug={slug} ownerType="enterprise">
      <div className="d-flex flex-column gap-3">
        <div className="d-flex flex-justify-between align-items-center width-full border-bottom color-border-default">
          <PageHeader>
            <PageHeader.TitleArea>
              <PageHeader.Title as="h1" className="mb-2">
                Enterprise role assignments
              </PageHeader.Title>
            </PageHeader.TitleArea>
          </PageHeader>
          <div className="flex-order-0 ml-auto d-lg-none d-xl-block flex-lg-order-0 mt-1">
            <BetaLabel>Preview</BetaLabel>
          </div>
        </div>
        <RoleAssignmentsTable
          usersCount={usersCount}
          teamsCount={teamsCount}
          roleType={RoleType.Enterprise}
          assignments={assignments}
          hasWriteAccess={hasWriteAccess}
          currentPage={currentPage}
          pageCount={pageCount}
          selectedTab={selectedTab}
          canViewEnterpriseTeams={canViewEnterpriseTeams}
          avatarOrgs={avatarOrgs}
          selectedRole={selectedRole}
          availableRoles={availableRoles}
        />
      </div>
    </RoutingProvider>
  )
}
