import {testIdProps} from '@github-ui/test-id-props'
import {useMutation} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {Button, Stack, Text} from '@primer/react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {useState} from 'react'
import {NewRoleAssignmentRadioGroup} from './NewRoleAssignmentRadioGroup'
import {NewRoleAssignmentAssigneeSelect} from './NewRoleAssignmentAssigneeSelect'
import {useBannerContext} from '@github-ui/role-assignments/banner-provider'
import type {Actor} from '../enterprise-role-assignments-types'
import {esmStatus, isEsm, showEsmWarning} from '../utils/role-utils'
import type {AvatarOrg, Role} from '@github-ui/role-assignments/types/role-assignments'
import {RoleAvatarSpread} from '@github-ui/role-assignments/role-avatar-spread'

export interface NewRoleAssignmentPageProps {
  roles: Role[]
  queryActorsPath: string
  submitAssignmentRoute: string
  avatarOrgs?: AvatarOrg[]
  enterpriseTeamOrgAssignmentLimitExceeded?: boolean
  cancelAction: () => void
}

type Result =
  | {
      error: string
      success?: false
    }
  | {
      success: true
      message: string
      redirect_url: string
    }

export function NewRoleAssignmentPage({
  roles,
  submitAssignmentRoute,
  queryActorsPath,
  cancelAction,
  avatarOrgs,
  enterpriseTeamOrgAssignmentLimitExceeded,
}: NewRoleAssignmentPageProps) {
  const {navigate, showBanner} = useBannerContext()
  const [assignee, setAssignee] = useState<Actor | null>(null)
  const [selectedRole, setSelectedRole] = useState<Role | null>(null)

  function handleActorSelect(actor: Actor) {
    if (
      selectedRole &&
      isEsm(selectedRole) &&
      esmStatus(actor.type, !!enterpriseTeamOrgAssignmentLimitExceeded).status === 'disabled'
    ) {
      setSelectedRole(null)
    }
    setAssignee(actor)
  }

  const {mutate, isPending} = useMutation<Result>({
    mutationFn: async () => {
      const response = await verifiedFetchJSON(submitAssignmentRoute, {
        method: 'POST',
        body: {role_id: selectedRole?.id, assignee_type: assignee?.type, assignee_id: assignee?.id},
      })

      // Potential expected errors, handled in onSuccess callback
      if (response.ok || response.status === 403 || response.status === 422) {
        const result = await response.json()
        if ('error' in result || 'success' in result) {
          return result
        }
        throw new Error('Unexpected JSON structure in response')
      }

      throw new Error(response.statusText)
    },
    onError: () => {
      showBanner({
        message: 'Something went wrong while assigning the role. Please try again later.',
        variant: 'critical',
      })
    },
    onSuccess: data => {
      if (data.success) {
        navigate(data.redirect_url, undefined, {
          message: data.message,
          variant: 'success',
        })
      } else {
        showBanner({
          message: data.error,
          variant: 'critical',
        })
      }
    },
  })

  return (
    <form onSubmit={handleSubmit}>
      <Stack gap="spacious" {...testIdProps('role-assignment-page')}>
        <Stack gap="normal">
          <NewRoleAssignmentAssigneeSelect queryActorsPath={queryActorsPath} onSelectCallback={handleActorSelect} />

          <Stack direction="vertical" gap="condensed">
            <NewRoleAssignmentRadioGroup
              roles={roles}
              assigneeType={assignee?.type}
              avatarOrgs={avatarOrgs}
              selectedRoleId={selectedRole?.id}
              enterpriseTeamOrgAssignmentLimitExceeded={enterpriseTeamOrgAssignmentLimitExceeded}
              onSelectCallback={handleRoleSelect}
            />

            {showEsmWarning(selectedRole, assignee) && (
              <div aria-live="polite" role="alert" {...testIdProps('esm-warning-message')}>
                <Stack direction="horizontal" align="center" className="gap-1 fgColor-muted">
                  <GitHubAvatar src={assignee.avatarUrl} alt={assignee.name} size={16} square />
                  {''}
                  <Text weight="semibold" className="fgColor-default">
                    {assignee.name}
                  </Text>{' '}
                  will be added to{' '}
                  {avatarOrgs && <RoleAvatarSpread avatarURLs={avatarOrgs.map(org => org.avatarURL)} />}
                  <Text weight="semibold" className="fgColor-default">
                    all organizations
                  </Text>
                </Stack>
              </div>
            )}
          </Stack>
        </Stack>

        <Stack direction="horizontal" gap="condensed">
          <Button variant="primary" type="submit" loading={isPending}>
            Assign role
          </Button>
          <Button disabled={isPending} onClick={cancelAction}>
            Cancel
          </Button>
        </Stack>
      </Stack>
    </form>
  )

  function handleRoleSelect(role: Role) {
    setSelectedRole(prevRoleAssigned => (prevRoleAssigned?.id === role.id ? null : role))
  }

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    if (!assignee || !selectedRole) {
      showBanner({message: 'Please select an actor and role to assign.', variant: 'warning'})
      return
    }
    mutate()
  }
}
